			/**
			 * 목록 데이터 조회
			 * @param psStatus - 조회 상태(저장 후 조회인 경우에는 'save' 구분값 넘김)
			 */
			function doList(psStatus) {
			    
			    //조회 서브미션 호출
			    util.Submit.send(app, "subList", function(pbSuccess) {
			        app.lookup("cmb1").focus();
			        if (pbSuccess) {
			            var dsStudntSlctList = app.lookup("dsReportStatsStudntSlctList");
			            var dayList = ['일', '월', '화', '수', '목', '금', '토'];
			            
			            for (var idx = 0; idx < dsStudntSlctList.getRowCount(); idx++) {
			                var a = dsStudntSlctList.getValue(idx, "PVSN_BGNG_YMD").replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3');
			                var b = dsStudntSlctList.getValue(idx, "PVSN_END_YMD").replace(/(\d{4})(\d{2})(\d{2})/, '$1-$2-$3');
			                var c = dayList[new Date(a).getDay()];
			                var d = dayList[new Date(b).getDay()];
			                dsStudntSlctList.setValue(idx, "PVSN_PRD_YMD", a + "(" + c + ") ~ " + b + "(" + d + ")");
			            }
			            dsStudntSlctList.setRowStateAll(cpr.data.tabledata.RowState.UNCHANGED);
			            
			            //2022년이면 특화교육이 있고 진로설계, 취업지원, 자립역량이 없음. 그 외는 반대로 풀어놓음(임시)
			            if (app.lookup("cmb1").value <= '2022') {
			                app.lookup("grdList").columnVisible(10, false);
			                app.lookup("grdList").columnVisible(11, false);
			                app.lookup("grdList").columnVisible(12, false);
			                app.lookup("grdList").columnVisible(13, true);
			                app.lookup("grdList").columnVisible(14, true);
			                app.lookup("grdList").columnVisible(15, false);
			            } else {
			                app.lookup("grdList").columnVisible(10, true);
			                app.lookup("grdList").columnVisible(11, true);
			                app.lookup("grdList").columnVisible(12, true);
			                app.lookup("grdList").columnVisible(13, false);
			                app.lookup("grdList").columnVisible(14, false);
			                app.lookup("grdList").columnVisible(15, true);
			            }
			            
			            if (psStatus == "save") {
			                //갱신된 데이터가 조회되었습니다.
			                util.Msg.notify(app, "INF-M005");
			            } else {
			                //조회되었습니다.
			                util.Msg.notify(app, "INF-M001");
			            }
			            app.lookup("grdList").redraw();
			            app.lookup("grpData").redraw();
			        }
			    });
			}

			/**
			 * 사업연도와 서비스실행사업에 따른 기관 콤보데이터 필터설정
			 */
			function setCmbInstFilter() {
			    
			    var cmb2 = app.lookup("cmb2");
			    var cmb1 = app.lookup("cmb1").value;
			    var voDsOperInst = app.lookup("dsInst");
			    
			    if (cmb2.getItemCount() == 1) {
			        voDsOperInst.forEachOfUnfilteredRows(function(row) {
			            row.setValue("FILTER", 'Y')
			        });
			    } else if (cmb1 == '') {
			        voDsOperInst.forEachOfUnfilteredRows(function(row) {
			            
			            row.setValue("FILTER", 'N');
			        });
			    } else {
			        voDsOperInst.forEachOfUnfilteredRows(function(row) {
			            var yrFilter = false;
			            var bizYrArr = row.getValue("BIZ_YR").split('|');
			            
			            for (var idx = 1; idx < bizYrArr.length; idx++) {
			                var bizYr = bizYrArr[idx];
			                if (bizYr == cmb1 || cmb1 == '')
			                    yrFilter = true;
			            }
			            
			            if (yrFilter)
			                row.setValue("FILTER", 'Y');
			            else
			                row.setValue("FILTER", 'N');
			        });
			    }
			    
			    if (cmb2.getItemCount() == 2)
			        cmb2.selectItem(1);
			    else if (!cmb2.findItem({
			            value: cmb2.value
			        }))
			        cmb2.selectItem(0);
			}

